Rule.Source:
// MNB HR Identity Mapping for manager
// Maps HR managersAssociateID to identity warehouse manager display name

String managersAssociateID = (String)link.getAttribute("managersAssociateID");
String managerName = (String)link.getAttribute("manager");

// If we have a manager associate ID, we can map to identity name
if (managersAssociateID != null && !managersAssociateID.isEmpty()) {
    // Use the provided manager name if available
    if (managerName != null && !managerName.isEmpty()) {
        return managerName;
    }
    // Otherwise, return the associate ID as fallback
    // This could be transformed to a full name lookup in a more complex rule
    return "Manager (" + managersAssociateID + ")";
}

return null;
